code.source:
#include <iomanip>
#include <iostream>
using namespace std;

int main() {
    cout << fixed << setprecision(2);
    cout << setw(8) << "Fish" << setw(8) << 120.5 << endl;
    cout << setw(8) << "Rice" << setw(8) << 45.0 << endl;
    cout << setw(8) << "Total" << setw(8) << 165.5 << endl;
    return 0;
}

#include <format>
#include <iostream>
#include <string>
using namespace std;

int main() {
    string line = format("{} costs {:.2f} rupees", "Fish", 120.5);
    cout << line << endl;
    return 0;
}

